const dns = require('dns');
const dgram = require('dgram');

const domain = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww.audit.test';
const server = 'localhost';
const port = 47302;

console.log(`Performing DNS lookup for: ${domain}`);
console.log(`Using DNS server: ${server}:${port}`);

// Create a simple DNS query packet (type A record)
function createDnsQuery(domain) {
  // Transaction ID (random)
  const id = Buffer.alloc(2);
  id.writeUInt16BE(Math.floor(Math.random() * 65536));

  // Flags: standard query, recursion desired
  const flags = Buffer.from([0x01, 0x00]);

  // Questions: 1
  const qdcount = Buffer.from([0x00, 0x01]);

  // Answer RRs: 0, Authority RRs: 0, Additional RRs: 0
  const ancount = Buffer.from([0x00, 0x00]);
  const nscount = Buffer.from([0x00, 0x00]);
  const arcount = Buffer.from([0x00, 0x00]);

  // Domain name (QNAME)
  const labels = domain.split('.');
  let qname = Buffer.alloc(0);
  for (const label of labels) {
    qname = Buffer.concat([qname, Buffer.from([label.length]), Buffer.from(label)]);
  }
  qname = Buffer.concat([qname, Buffer.from([0x00])]); // Null terminator

  // QTYPE: A record (1), QCLASS: IN (1)
  const qtype = Buffer.from([0x00, 0x01]);
  const qclass = Buffer.from([0x00, 0x01]);

  return Buffer.concat([id, flags, qdcount, ancount, nscount, arcount, qname, qtype, qclass]);
}

const query = createDnsQuery(domain);
const client = dgram.createSocket('udp4');

client.on('message', (msg, rinfo) => {
  console.log(`Received response from ${rinfo.address}:${rinfo.port}`);
  console.log(`Response (hex): ${msg.toString('hex')}`);

  // Parse the response (simple parsing)
  // Check if it's a valid response (response flag should be set)
  const rcode = msg[3] & 0x0F;
  const ancount = msg.readUInt16BE(6);

  console.log(`Response code: ${rcode}`);
  console.log(`Answer count: ${ancount}`);

  if (ancount > 0) {
    // Parse answers (simple approach)
    console.log('DNS lookup successful - answer(s) received');
  } else if (rcode === 0) {
    console.log('DNS lookup successful - no error but no answers');
  } else {
    console.log(`DNS lookup failed with RCODE: ${rcode}`);
  }

  client.close();
});

client.on('error', (err) => {
  console.error(`Socket error: ${err.message}`);
  client.close();
});

// Set timeout
setTimeout(() => {
  console.log('Timeout - no response received');
  client.close();
  process.exit(1);
}, 5000);

console.log('Sending DNS query...');
client.send(query, port, server, (err) => {
  if (err) {
    console.error(`Send error: ${err.message}`);
    client.close();
  } else {
    console.log('DNS query sent successfully');
  }
});

