    client.setTimeout(5000);

    client.connect(47302, 'localhost', () => {
        console.log('Connected to DNS server');
        client.write(query);
    });

    let response = Buffer.alloc(0);
    client.on('data', (data) => {
        response = Buffer.concat([response, data]);
        // Parse DNS response - simple check for now
        console.log('Received response of length:', response.length);

        // Check if response has answer section
        if (response.length > 12) {
            const answerCount = response.readUInt16BE(6);
            console.log('Answer count:', answerCount);

            if (answerCount > 0) {
                // Success - got at least one answer
                console.log('DNS query successful');
                process.exit(0);
            }
        }

        client.destroy();
    });

    client.on('error', (err) => {
        console.log('Connection error:', err.message);
    });

    client.on('timeout', () => {
        console.log('Connection timeout');
        client.destroy();
    });

    client.on('close', () => {
        console.log('Connection closed');
        if (response.length === 0) {
            console.log('No response received');
        }
    });

    setTimeout(() => {
        if (client && !client.destroyed) {
            client.destroy();
        }
        process.exit(1);
    }, 10000);
}

